// "Link dead or closed" verdict (n8n Code node, runs once for each listing)
// The apply page returned 404/410 or says applications are closed. Not a scam judgement:
// the card is greyed out on the dashboard as expired, and nothing is sent to the AI stages.

function expiredVerdict(listing, link) {
  const why = link.link_state === "closed"
    ? `Apply page says "${link.closed_phrase}"`
    : `Apply page returned HTTP ${link.http_status} (${link.link_state})`;
  return { id: listing.id, status: "expired", scam_risk: 0, reasons: [why], decided_by: "link_check" };
}

// ==== n8n glue (below this line runs only inside n8n) ====
return { json: { verdict: expiredVerdict($('Fetch pending listings').item.json, $json) } };

// Stage 0 — "Link + contact signals" (n8n Code node, runs once for each listing)
// Deterministic checks on the apply link (where it redirects) and on contact details in the
// post, then cuts the post into short chunks and prepares one embedding request for them.
// No AI here: every signal is a rule a human can read and argue with.

const SHORTENERS = ["bit.ly", "tinyurl.com", "t.co", "cutt.ly", "rb.gy", "shorturl.at", "is.gd", "goo.gl",
  "tiny.cc", "rebrand.ly", "shorturl.com", "s.id"];
const FORM_SITES = ["forms.gle", "docs.google.com/forms", "forms.office.com", "typeform.com", "jotform.com", "tally.so"];
const CHAT_SITES = ["wa.me", "api.whatsapp.com", "chat.whatsapp.com", "t.me", "telegram.me"];
const UPI_RE = /\b[\w.\-]{2,}@(okaxis|okhdfcbank|okicici|oksbi|ybl|ibl|axl|paytm|upi|apl|fbl|ptyes|ptsbi|ikwik|jupiteraxis)\b/i;
const FREE_MAIL_RE = /\b[\w.+-]+@(gmail|yahoo|outlook|hotmail|rediffmail)\.com\b/i;
const PHONE_RE = /(?:\+91[\s-]?)?\b[6-9]\d{9}\b/;
const WHATSAPP_RE = /\bwhats\s?app\b/i;
const TELEGRAM_RE = /\btelegram\b/i;

function hostOf(url) {
  try { return new URL(url).hostname.toLowerCase().replace(/^www\./, ""); } catch (e) { return ""; }
}

function matchesSite(url, sites) {
  const u = String(url || "").toLowerCase().replace(/^https?:\/\/(www\.)?/, "");
  return sites.find(s => u === s || u.startsWith(s + "/") || u.startsWith(s + "?") || hostOf("https://" + u) === s) || null;
}

function linkSignals(listing, link) {
  const out = [];
  const urls = [listing.apply_link, ...(link.chain || []), link.final_url].filter(Boolean);
  for (const [sites, code, label, weight] of [
    [CHAT_SITES, "chat_link", "Apply link opens WhatsApp/Telegram instead of an application page", 0.35],
    [SHORTENERS, "short_link", "Apply link goes through a link shortener, hiding where it leads", 0.25],
    [FORM_SITES, "form_link", "Applications are collected on a generic form, not the portal or company site", 0.2],
  ]) {
    const hit = urls.map(u => matchesSite(u, sites)).find(Boolean);
    if (hit) out.push({ code, label: `${label} (${hit})`, weight });
  }
  const start = hostOf(listing.apply_link), end = link.final_domain || hostOf(link.final_url);
  if (start && end && start !== end && !end.endsWith("." + start) && !start.endsWith("." + end)) {
    out.push({ code: "redirect", label: `Link redirects from ${start} to ${end}`, weight: 0.1 });
  }
  if (link.link_state === "bad_certificate") {
    out.push({ code: "bad_cert", label: "Apply page has a broken security certificate", weight: 0.15 });
  }
  return out;
}

function textSignals(listing) {
  const text = `${listing.role_title || ""} ${listing.description || ""}`;
  const out = [];
  const upi = text.match(UPI_RE);
  if (upi) out.push({ code: "upi_id", label: `Post contains a UPI payment ID (${upi[0]})`, weight: 0.5 });
  const mail = text.match(FREE_MAIL_RE);
  if (mail) out.push({ code: "free_mail", label: `Recruiter uses a free email address (${mail[0]})`, weight: 0.15 });
  if (WHATSAPP_RE.test(text)) out.push({ code: "whatsapp", label: "Post asks candidates to use WhatsApp", weight: 0.15 });
  if (TELEGRAM_RE.test(text)) out.push({ code: "telegram", label: "Post mentions Telegram", weight: 0.2 });
  if (PHONE_RE.test(text)) out.push({ code: "phone", label: "Personal phone number in the post", weight: 0.1 });
  const flags = String(listing.trust_flags || "").split(";").map(f => f.trim()).filter(Boolean);
  if (flags.length) {
    out.push({ code: "scraper_flags", label: `Scraper warnings: ${flags.join("; ")}`, weight: Math.min(0.3, 0.07 * flags.length) });
  }
  return out;
}

// Combines independent signals: 1 - (1-w1)(1-w2)...
function combine(signals) {
  return Math.min(0.95, 1 - signals.reduce((p, s) => p * (1 - s.weight), 1));
}

function chunkText(listing, maxChunks = 30) {
  const head = `${listing.role_title || ""} at ${listing.company_name || ""}. Stipend: ${listing.stipend || "not stated"}.`;
  const body = String(listing.description || "").replace(/\s+/g, " ").trim();
  const sentences = body.split(/(?<=[.!?।])\s+|\s*[•●▪]\s*|\s+-\s+(?=[A-Z])/).map(s => s.trim()).filter(Boolean);
  const chunks = [head];
  let carry = "";
  for (const s of sentences) {
    const words = (carry ? carry + " " + s : s).split(" ");
    carry = "";
    if (words.length < 5) { carry = words.join(" "); continue; }
    if (words.length <= 45) { chunks.push(words.join(" ")); continue; }
    for (let i = 0; i < words.length; i += 25) {        // long sentence: 35-word windows, 10 overlap
      chunks.push(words.slice(i, i + 35).join(" "));
      if (i + 35 >= words.length) break;
    }
  }
  if (carry) chunks.push(carry);
  return chunks.slice(0, maxChunks);
}

function embedRequest(chunks, bank) {
  const model = `models/${bank.model}`;
  return {
    requests: chunks.map(text => {
      const item = { model, content: { parts: [{ text }] } };
      if (bank.request_style === "config") item.embedContentConfig = { taskType: bank.task_type, outputDimensionality: bank.dims };
      if (bank.request_style === "legacy") { item.taskType = bank.task_type; item.outputDimensionality = bank.dims; }
      return item;
    }),
  };
}

function analyse(listing, link, bank) {
  const signals = [...linkSignals(listing, link || {}), ...textSignals(listing)];
  const chunks = chunkText(listing);
  return {
    id: listing.id,
    link: { state: (link || {}).link_state || "unknown", http_status: (link || {}).http_status || null,
            final_domain: (link || {}).final_domain || "", chain: (link || {}).chain || [] },
    signals,
    signal_risk: Number(combine(signals).toFixed(3)),
    chunks,
    embedRequest: embedRequest(chunks, bank),
  };
}

// ==== n8n glue (below this line runs only inside n8n) ====
const listing = $('Fetch pending listings').item.json;
const bank = $('Fetch pattern bank').first().json;
return { json: analyse(listing, $json, bank) };

// Stage 1 — "Vector search vs scam patterns" (n8n Code node, runs once for each listing)
// Each chunk of the post is compared by cosine similarity with every phrase in the pattern
// bank (moderation/scam_patterns.json). A chunk only counts as a hit when it is
//   (a) about as close to a scam phrase as two phrasings of the same trick are to each other, and
//   (b) clearly closer to that scam phrase than to the nearest HONEST phrase.
// (b) is what keeps "There is no registration fee" from matching "Pay the registration fee".
// Thresholds come from the bank itself (build_index.py calibration) and can be overridden in Config.

const SEVERITY_WEIGHT = { high: 0.9, medium: 0.6, low: 0.3 };

function unit(values, dims) {
  const v = values.slice(0, dims);
  const n = Math.sqrt(v.reduce((s, x) => s + x * x, 0)) || 1;
  return v.map(x => x / n);
}

function dot(a, b) {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
}

function search(chunks, embeddings, bank, cfg) {
  const cal = { ...bank.calibration, ...Object.fromEntries(Object.entries(cfg || {}).filter(([, v]) => v !== "" && v != null)) };
  const hitFloor = Number(cal.hit_floor), strongFloor = Number(cal.strong_floor), margin = Number(cal.margin);
  const scam = bank.items.filter(it => it.kind === "scam");
  const honest = bank.items.filter(it => it.kind === "genuine");

  const perChunk = chunks.map((text, i) => {
    const v = unit(embeddings[i].values, bank.dims);
    let best = null, bestHonest = null;
    for (const it of scam) { const s = dot(v, it.vector); if (!best || s > best.sim) best = { sim: s, item: it }; }
    for (const it of honest) { const s = dot(v, it.vector); if (!bestHonest || s > bestHonest.sim) bestHonest = { sim: s, item: it }; }
    const m = best.sim - (bestHonest ? bestHonest.sim : 0);
    return {
      chunk: text, sim: best.sim, margin: m, pattern: best.item, honest: bestHonest ? bestHonest.item.text : "",
      hit: best.sim >= hitFloor && m >= margin,
      strong: best.sim >= strongFloor && m >= 2 * margin,
    };
  });

  // Strongest hit per category
  const byCategory = {};
  for (const c of perChunk.filter(c => c.hit)) {
    const cat = c.pattern.category;
    if (!byCategory[cat] || c.sim > byCategory[cat].sim) byCategory[cat] = c;
  }
  const categories = Object.values(byCategory).map(c => ({
    category: c.pattern.category,
    label: c.pattern.label,
    severity: c.pattern.severity,
    strong: c.strong,
    strength: Number(((SEVERITY_WEIGHT[c.pattern.severity] || 0.3) * (c.strong ? 1 : 0.6)).toFixed(3)),
    similarity: Number(c.sim.toFixed(3)),
    margin: Number(c.margin.toFixed(3)),
    chunk: c.chunk,
    matched_pattern: c.pattern.text,
  })).sort((a, b) => b.strength - a.strength);

  const vectorRisk = 1 - categories.reduce((p, c) => p * (1 - c.strength), 1);
  const nearest = perChunk.slice().sort((a, b) => b.sim - a.sim).slice(0, 3)
    .map(c => ({ chunk: c.chunk, pattern: c.pattern.text, similarity: Number(c.sim.toFixed(3)), margin: Number(c.margin.toFixed(3)) }));
  return {
    thresholds: { hit_floor: hitFloor, strong_floor: strongFloor, margin },
    chunks_checked: chunks.length,
    categories,
    vector_risk: Number(vectorRisk.toFixed(3)),
    nearest,     // shown even without a hit, so a reviewer can see how close the post came
  };
}

// Stage-1 gate: block without asking the LLM only on strong, high-severity evidence
function gate(stage1, signals) {
  const strongHigh = stage1.categories.filter(c => c.severity === "high" && c.strong);
  const upi = signals.find(s => s.code === "upi_id");
  const feeHit = stage1.categories.find(c => c.category === "upfront_fee");
  if (strongHigh.length) return { decision: "block", why: `Near-copy of a known scam: ${strongHigh.map(c => c.label).join(", ")}` };
  if (upi && feeHit) return { decision: "block", why: "Payment wording together with a UPI payment ID" };
  return { decision: "judge", why: "No conclusive match; sent to the LLM judge" };
}

// ==== n8n glue (below this line runs only inside n8n) ====
const prev = $('Link + contact signals').item.json;
const bank = $('Fetch pattern bank').first().json;
const cfg = $('Config').first().json;
const embeddings = ($json.embeddings || []);
if (embeddings.length !== prev.chunks.length) {
  // Embedding call failed: skip the vector stage, the LLM judge still runs and the reason says so
  const stage1 = { error: `Embedding failed (${$json.error ? JSON.stringify($json.error).slice(0, 200) : "no vectors"})`,
                   categories: [], vector_risk: 0, nearest: [], chunks_checked: 0 };
  return { json: { ...prev, embedRequest: undefined, stage1, gate: { decision: "judge", why: stage1.error } } };
}
const stage1 = search(prev.chunks, embeddings, bank, {
  hit_floor: cfg.hitFloor, strong_floor: cfg.strongFloor, margin: cfg.margin,
});
return { json: { ...prev, embedRequest: undefined, stage1, gate: gate(stage1, prev.signals) } };

// Shared by the three "verdict" Code nodes (the builder pastes it on top of each).
// Final status from the fused risk: blocked >= blockAt, review >= reviewAt, else approved.

function decide(risk, cfg, forceReview) {
  const blockAt = Number(cfg.blockAt ?? 0.7), reviewAt = Number(cfg.reviewAt ?? 0.4);
  let status = risk >= blockAt ? "blocked" : risk >= reviewAt ? "review" : "approved";
  if (forceReview && status === "approved") status = "review";
  return status;
}

function stageReasons(item) {
  const r = [];
  for (const c of (item.stage1 && item.stage1.categories) || []) {
    r.push(`Vector match, ${c.label} (similarity ${c.similarity}${c.strong ? ", near-copy" : ""}): "${c.chunk.slice(0, 160)}"`);
  }
  for (const s of item.signals || []) r.push(s.label);
  if (item.stage1 && item.stage1.error) r.push(item.stage1.error);
  return r;
}

// Stage 1 verdict — "Blocked at stage 1" (n8n Code node, runs once for each listing)
// Reached only when the vector search found a near-copy of a high-severity scam phrase
// (or payment wording plus a UPI ID). The LLM is not asked: the evidence is already explicit.

function stage1Verdict(item, cfg) {
  const risk = Math.max(Number(cfg.blockAt ?? 0.7), 0.6 + 0.4 * item.stage1.vector_risk, item.signal_risk);
  return {
    id: item.id,
    status: decide(risk, cfg, false),
    scam_risk: Number(Math.min(0.99, risk).toFixed(2)),
    reasons: [`Stage 1: ${item.gate.why}`, ...stageReasons(item)],
    decided_by: "vector_search",
  };
}

// ==== n8n glue (below this line runs only inside n8n) ====
return { json: { verdict: stage1Verdict($json, $('Config').first().json) } };

// Stage 2a — "Build one-shot judge request" (n8n Code node, runs once for each listing)
// Builds ONE request for the LLM: rules, one worked example (one-shot), then the listing with
// the stage-0/1 findings as leads to verify. The answer must follow a fixed JSON schema and
// quote the post word for word, because the next node throws away any quote it can't find.

const CATEGORIES = ["upfront_fee", "task_scam", "data_harvest", "off_platform_contact",
  "too_good_to_be_true", "pressure", "training_sale", "mlm", "none"];

const SYSTEM = [
  "You review internship posts for an Indian student job board and estimate how likely each one is a scam.",
  "Judge ONLY from the post text given. Do not assume facts about the company that are not in the text.",
  "Scam signs: asking the candidate for any payment (registration, training, kit, certificate, deposit, 'refundable' money);",
  "paid online tasks (likes, reviews, Telegram tasks); asking for Aadhaar/PAN/bank details/OTP before selection;",
  "moving candidates to WhatsApp/Telegram/personal Gmail; 'no interview, everyone selected'; pay far above normal for no skills;",
  "deadline pressure to pay; a paid course or certificate sold as an internship; pay that depends on recruiting others.",
  "Not scam signs on their own: small or unknown company, short description, low stipend, remote work, a recruiter posting.",
  "A post that says it does NOT charge fees is a good sign, not a bad one.",
  "Every evidence quote must be copied EXACTLY from the post (5 to 25 words). If there is no evidence, return an empty list.",
  "scam_probability: 0.0 = clearly genuine, 0.5 = cannot tell, 1.0 = clearly a scam. Be calibrated: most posts on job boards are genuine.",
  "The 'automated findings' come from keyword and similarity checks and can be wrong. Confirm or reject them from the text.",
].join("\n");

const EXAMPLE_POST = [
  "Title: Data Science Intern",
  "Company: Brightpath Analytics",
  "Stipend: 25,000/month",
  "Text: Work on real projects in Python and ML. Selected candidates must pay a refundable security deposit of Rs 1,500 " +
    "for the internship kit. Contact HR on WhatsApp 98xxxxxx10 to get your offer letter today, only 5 seats left.",
  "Automated findings: upfront_fee (similarity 0.86) | Post asks candidates to use WhatsApp",
].join("\n");

const EXAMPLE_ANSWER = {
  scam_probability: 0.93,
  verdict: "scam",
  categories: ["upfront_fee", "off_platform_contact", "pressure"],
  evidence: [
    { quote: "Selected candidates must pay a refundable security deposit of Rs 1,500", why: "Genuine internships never charge a deposit." },
    { quote: "Contact HR on WhatsApp", why: "Moves hiring off the platform to an unverifiable chat." },
    { quote: "only 5 seats left", why: "Pressure to act before checking." },
  ],
  genuine_signs: ["Mentions Python and ML project work"],
  summary: "Asks for a refundable deposit and pushes candidates to WhatsApp with seat pressure: classic deposit scam.",
};

const SCHEMA = {
  type: "OBJECT",
  properties: {
    scam_probability: { type: "NUMBER" },
    verdict: { type: "STRING", enum: ["genuine", "suspicious", "scam"] },
    categories: { type: "ARRAY", items: { type: "STRING", enum: CATEGORIES } },
    evidence: {
      type: "ARRAY",
      items: { type: "OBJECT", properties: { quote: { type: "STRING" }, why: { type: "STRING" } }, required: ["quote", "why"] },
    },
    genuine_signs: { type: "ARRAY", items: { type: "STRING" } },
    summary: { type: "STRING" },
  },
  required: ["scam_probability", "verdict", "categories", "evidence", "summary"],
};

function findingsLine(item) {
  const parts = (item.stage1.categories || []).map(c => `${c.category} (similarity ${c.similarity}): "${c.chunk}"`);
  for (const s of item.signals || []) parts.push(s.label);
  return parts.length ? parts.join(" | ") : "none";
}

function buildRequest(listing, item) {
  const post = [
    `Title: ${listing.role_title}`,
    `Company: ${listing.company_name}`,
    `Stipend: ${listing.stipend || "not stated"}`,
    `Source: ${listing.source_platform}`,
    `Text: ${String(listing.description || "(no description was available)").slice(0, 3000)}`,
    `Automated findings: ${findingsLine(item)}`,
  ].join("\n");
  return {
    systemInstruction: { parts: [{ text: SYSTEM }] },
    contents: [
      { role: "user", parts: [{ text: EXAMPLE_POST }] },
      { role: "model", parts: [{ text: JSON.stringify(EXAMPLE_ANSWER) }] },
      { role: "user", parts: [{ text: post }] },
    ],
    generationConfig: { temperature: 0, responseMimeType: "application/json", responseSchema: SCHEMA },
  };
}

// ==== n8n glue (below this line runs only inside n8n) ====
const listing = $('Fetch pending listings').item.json;
return { json: { ...$json, judgeRequest: buildRequest(listing, $json) } };

// Shared by the three "verdict" Code nodes (the builder pastes it on top of each).
// Final status from the fused risk: blocked >= blockAt, review >= reviewAt, else approved.

function decide(risk, cfg, forceReview) {
  const blockAt = Number(cfg.blockAt ?? 0.7), reviewAt = Number(cfg.reviewAt ?? 0.4);
  let status = risk >= blockAt ? "blocked" : risk >= reviewAt ? "review" : "approved";
  if (forceReview && status === "approved") status = "review";
  return status;
}

function stageReasons(item) {
  const r = [];
  for (const c of (item.stage1 && item.stage1.categories) || []) {
    r.push(`Vector match, ${c.label} (similarity ${c.similarity}${c.strong ? ", near-copy" : ""}): "${c.chunk.slice(0, 160)}"`);
  }
  for (const s of item.signals || []) r.push(s.label);
  if (item.stage1 && item.stage1.error) r.push(item.stage1.error);
  return r;
}

// Stage 2b — "Verify evidence + fuse scores" (n8n Code node, runs once for each listing)
// The LLM's answer is treated as one witness, not the judge:
//   1. every quote it gives is searched for in the real post; quotes that aren't there are thrown out
//   2. a high scam probability with no surviving quote is pulled back towards 0.5 ("can't tell")
//   3. the LLM, the vector search and the link/contact rules are combined with fixed weights,
//      so the LLM alone can push a post to "review" but never to "blocked"
//   4. if the LLM and the vector search strongly disagree, a human looks at it

const WEIGHTS = { llm: 0.6, vector: 0.25, signals: 0.15 };

function norm(s) {
  return String(s || "").toLowerCase().replace(/[“”"'’`]/g, "").replace(/[^a-z0-9₹%@.\s]/g, " ").replace(/\s+/g, " ").trim();
}

function parseLlm(resp) {
  try {
    const parts = resp.candidates[0].content.parts;
    const text = parts.map(p => p.text || "").join("");
    const j = JSON.parse(text);
    const p = Number(j.scam_probability);
    if (!(p >= 0 && p <= 1)) throw new Error("scam_probability missing");
    return { ok: true, ...j, scam_probability: p };
  } catch (e) {
    const why = resp && resp.error ? JSON.stringify(resp.error).slice(0, 200) : String(e.message || e);
    return { ok: false, error: why };
  }
}

// A quote like "We do not charge any fee" is in the post, but it argues AGAINST a scam
const NEGATED_MONEY_RE = /\b(no|not|never|zero|without|free of|nil|dont|doesnt|wont)\b[^.]{0,40}\b(fee|fees|charge|charges|payment|pay|deposit|money)\b/i;

function verifyEvidence(listing, evidence) {
  const source = norm([listing.role_title, listing.company_name, listing.stipend, listing.description].join(" "));
  const verified = [], rejected = [], contradicting = [];
  for (const ev of evidence || []) {
    const q = norm(ev.quote);
    if (!(q.length >= 8 && source.includes(q))) rejected.push(ev);
    else if (NEGATED_MONEY_RE.test(q)) contradicting.push(ev);
    else verified.push(ev);
  }
  return { verified, rejected, contradicting };
}

function fuse(listing, item, resp, cfg) {
  const llm = parseLlm(resp);
  const reasons = [];
  let pAdj = null, verified = [], rejected = [], contradicting = [];

  if (llm.ok) {
    ({ verified, rejected, contradicting } = verifyEvidence(listing, llm.evidence));
    pAdj = llm.scam_probability;
    if (pAdj > 0.5 && verified.length === 0) {
      pAdj = 0.5 + (pAdj - 0.5) * 0.25;          // a claim without proof counts for little
      reasons.push(`LLM said ${llm.verdict} (${llm.scam_probability}) but quoted nothing found in the post, so it was discounted`);
    }
    if (rejected.length) reasons.push(`Ignored ${rejected.length} LLM quote(s) that are not in the post`);
    for (const ev of contradicting) reasons.push(`Ignored LLM quote that says the opposite (no fee): "${ev.quote}"`);
  } else {
    reasons.push(`LLM judge unavailable (${llm.error}); decided on stage-1 evidence only`);
  }

  const v = item.stage1.vector_risk, s = item.signal_risk;
  let risk;
  if (pAdj === null) {
    risk = Math.max(0.4 * v + 0.2 * s, v >= 0.5 ? 0.4 : 0);   // no LLM: never auto-approve a vector hit
  } else {
    risk = WEIGHTS.llm * pAdj + WEIGHTS.vector * v + WEIGHTS.signals * s;
  }
  const disagree = pAdj !== null && Math.abs(pAdj - v) >= 0.6;
  if (disagree) reasons.push(`LLM (${pAdj.toFixed(2)}) and vector search (${v.toFixed(2)}) disagree, so a person should check`);

  if (llm.ok) {
    reasons.unshift(`LLM: ${llm.verdict}, probability ${llm.scam_probability} — ${llm.summary || ""}`.trim());
    for (const ev of verified.slice(0, 3)) reasons.push(`Quote: "${ev.quote}" (${ev.why})`);
  }
  reasons.push(...stageReasons(item));

  return {
    id: item.id,
    status: decide(risk, cfg, disagree),
    scam_risk: Number(Math.min(0.99, Math.max(0, risk)).toFixed(2)),
    reasons,
    decided_by: llm.ok ? "fusion" : "vector_search",
    parts: { llm_raw: llm.ok ? llm.scam_probability : null, llm_adjusted: pAdj === null ? null : Number(pAdj.toFixed(3)),
             vector_risk: v, signal_risk: s, verified_quotes: verified.length, rejected_quotes: rejected.length + contradicting.length },
  };
}

// ==== n8n glue (below this line runs only inside n8n) ====
const listing = $('Fetch pending listings').item.json;
const item = $('Build one-shot judge request').item.json;
return { json: { verdict: fuse(listing, item, $json, $('Config').first().json) } };
